<!doctype html><html><head><meta charset="utf-8"><title>Party Statement</title><style>body{font:12px Arial;color:#182536}h1{text-align:center;font-size:18px}.meta{text-align:center;margin-bottom:15px}table{width:100%;border-collapse:collapse}th,td{padding:7px;border-bottom:1px solid #ccd5df;text-align:left}th:nth-last-child(-n+3),td:nth-last-child(-n+3){text-align:right}footer{margin-top:18px;text-align:right}@media print{@page{size:landscape;margin:12mm}}</style></head><body><h1>{{ $statement['filters']['type']==='vendor' ? 'VENDOR ACCOUNT STATEMENT' : 'CUSTOMER ACCOUNT STATEMENT' }}</h1><div class="meta">Currency: PKR · {{ $statement['filters']['from'] }} to {{ $statement['filters']['to'] }}</div><table><thead><tr><th>Date</th><th>Type</th><th>Reference</th><th>Booking No.</th><th>Product</th><th>Passenger / Group</th><th>Service Ref.</th><th>Sector / Description</th><th>Debit (PKR)</th><th>Credit (PKR)</th><th>Balance (PKR)</th></tr></thead><tbody>@foreach($statement['rows'] as $row)<tr><td>{{ $row['date'] }}</td><td>{{ $row['type'] }}</td><td>{{ $row['reference'] ?: '—' }}</td><td>{{ $row['booking_no'] }}</td><td>{{ $row['product'] }}</td><td>{{ $row['party'] }}</td><td>{{ $row['service_ref'] }}</td><td>{{ $row['description'] }}</td><td>{{ number_format($row['debit'],2) }}</td><td>{{ number_format($row['credit'],2) }}</td><td>{{ number_format(abs($row['balance']),2) }} {{ $row['balance'] < 0 ? 'Cr' : 'Dr' }}</td></tr>@endforeach</tbody></table><footer>Opening {{ number_format(abs($statement['opening']),2) }} · Debit {{ number_format($statement['total_debit'],2) }} · Credit {{ number_format($statement['total_credit'],2) }} · Closing {{ number_format(abs($statement['closing']),2) }} {{ $statement['closing_side'] }}<br>{{ $statement['caption'] }}</footer></body></html>
